WITH recent_departments AS (SELECT * FROM departments WHERE location = 'New York'), budget_bucket_summary AS (SELECT CASE WHEN budget >= 4093000 THEN 'high' WHEN budget >= 1725000 THEN 'mid' ELSE 'low' END budget_bucket, ROUND(STDDEV(budget), 2) stddev_budget FROM recent_departments GROUP BY CASE WHEN budget >= 4093000 THEN 'high' WHEN budget >= 1725000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, stddev_budget FROM budget_bucket_summary
